"""The code generated by a monitored circuit, as a function of depth.

Purification picture: every system qubit starts Bell-paired with its own
reference, so the system is maximally mixed and holds ``n`` logical qubits.
Measurements purify it; at each checkpoint this records

* the code dimension k (logical qubits left),
* the contiguous code distance (shortest run of qubits whose erasure leaks
  logical information),
* the probability that a uniformly random erasure of each size m is
  correctable, from which the failure probability under i.i.d. erasure with
  rate e follows exactly (``analysis.bernoulli_erasure_curve``).

    python v3/examples/code_and_erasure.py --n 128 --p 0.08 --layers 256 --every 16 --out code.npz

The result file is an ``EnsembleResult`` (``mipt.EnsembleResult.load``).
"""

from __future__ import annotations

import argparse

import numpy as np

from sparsegf2_v3 import analysis, graphs, mipt


def main() -> None:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    ap.add_argument("--n", type=int, default=128)
    ap.add_argument("--p", type=float, default=0.08)
    ap.add_argument("--layers", type=int, default=256)
    ap.add_argument("--every", type=int, default=16, help="checkpoint stride in layers")
    ap.add_argument("--trajectories", type=int, default=500)
    ap.add_argument("--erasure-samples", type=int, default=8)
    ap.add_argument("--graph", choices=["ring", "ws"], default="ring")
    ap.add_argument("--beta", type=float, default=0.1)
    ap.add_argument("--seed", type=int, default=1)
    ap.add_argument("--out", default="code_and_erasure.npz")
    args = ap.parse_args()

    n = args.n
    edges = (
        graphs.cycle(n) if args.graph == "ring" else graphs.watts_strogatz(n, 4, args.beta, seed=0)
    )
    spec = mipt.MonitoredCircuit(
        num_system=n,
        edges=edges,
        layers=args.layers,
        measurement_rate=args.p,
        schedule="matching",
        reference="purification",
        checkpoints=args.every,
        probes=[
            mipt.code_dimension(),
            mipt.contiguous_distance(),
            mipt.erasure_correctable_profile(samples=args.erasure_samples),
        ],
    )
    res = spec.run(args.trajectories, seed=args.seed)
    print(res)
    k = res.mean("code_dimension")
    d = res.mean("contiguous_distance")
    profile = res.mean("erasure_correctable_profile")  # (checkpoints, n + 1)
    rates = np.array([0.01, 0.02, 0.05, 0.1])
    print(" layer      k/n    d    P_fail(e) for e = " + " ".join(f"{e:5.2f}" for e in rates))
    for i, layer in enumerate(res.checkpoint_layers):
        fail = analysis.bernoulli_erasure_curve(1.0 - profile[i], rates)
        print(f"{layer:6d}  {k[i] / n:7.3f} {d[i]:5.1f}    " + " ".join(f"{f:5.3f}" for f in fail))
    res.save(args.out)
    print(f"saved {args.out}")


if __name__ == "__main__":
    main()
